'use strict';
// Local media commands only. The companion invokes these only for user-enabled
// ducking/bedtime options; no command is generated by this channel itself.
const {randomUUID}=require('node:crypto');
module.exports=function companionControl(){
 const clients=new Set(),pending=new Map();
 const local=req=>['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress);
 const json=(res,status,data)=>{if(res.destroyed||res.writableEnded)return;res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(data));};
 const read=(req,res,callback)=>{let size=0,chunks=[],failed=false;req.on('data',chunk=>{size+=chunk.length;if(size>1024){failed=true;chunks=[];json(res,413,{error:'Request too large'});}else if(!failed)chunks.push(chunk);});req.on('end',()=>{if(failed)return;try{const data=JSON.parse(Buffer.concat(chunks).toString('utf8'));if(!data||Array.isArray(data)||typeof data!=='object')throw Error();callback(data);}catch(_){json(res,400,{error:'Invalid media command'});}});req.on('error',()=>{});};
 function route(req,res,pathname){
  if(!local(req)){json(res,403,{error:'Local access only'});return;}
  if(pathname==='/api/companion-control/events'&&req.method==='GET'){
   res.writeHead(200,{'Content-Type':'text/event-stream','Cache-Control':'no-store','Connection':'keep-alive'});res.write('event: ready\ndata: {}\n\n');clients.add(res);
   req.on('close',()=>clients.delete(res));return;
  }
  if(pathname==='/api/companion-control/command'&&req.method==='POST'){
   read(req,res,data=>{
    if(!['pause','play','volume'].includes(data.command)||data.command==='volume'&&(!Number.isFinite(data.value)||data.value<0||data.value>1)){json(res,400,{error:'Unsupported media command'});return;}
    const client=Array.from(clients).at(-1);if(!client||client.destroyed){json(res,503,{error:'PAIN player window is not connected'});return;}
    const id=randomUUID(),timer=setTimeout(()=>{pending.delete(id);json(res,504,{error:'PAIN player did not acknowledge the command'});},2000);timer.unref();
    pending.set(id,{res,timer});res.on('close',()=>{const request=pending.get(id);if(request){clearTimeout(request.timer);pending.delete(id);}});
    client.write('event: control\ndata: '+JSON.stringify({id,command:data.command,...(data.command==='volume'?{value:data.value}:{})})+'\n\n');
   });return;
  }
  if(pathname==='/api/companion-control/result'&&req.method==='POST'){
   read(req,res,data=>{
    const request=pending.get(data.id);if(!request){json(res,404,{error:'Unknown media command'});return;}
    pending.delete(data.id);clearTimeout(request.timer);
    const result={ok:data.ok===true,playing:data.playing===true,volume:Number.isFinite(data.volume)?Math.max(0,Math.min(1,data.volume)):null};
    if(!result.ok)result.error=String(data.error||'Playback command failed').slice(0,160);
    json(request.res,result.ok?200:409,result);json(res,200,{ok:true});
   });return;
  }
  json(res,405,{error:'Method not allowed'});
 }
 const heartbeat=setInterval(()=>{for(const client of clients){if(client.destroyed)clients.delete(client);else client.write(': keepalive\n\n');}},15000);heartbeat.unref();
 return {route,close(){clearInterval(heartbeat);for(const client of clients)client.end();clients.clear();for(const {res,timer} of pending.values()){clearTimeout(timer);json(res,503,{error:'PAIN stopped'});}pending.clear();}};
};
